}

export function test(): int {
  let total: int = 0;
  let i: int = 1;
  while (i <= 4) {
    let acc: int = 0;
    let j: int = 1;
    while (j <= i) {
      acc = acc + j;
      j = j + 1;
    }
    total = total + acc;
    i = i + 1;
  }
  return total;
}

